// Extract filename from GitHub webhook
const modified = $input.first().json.body.commits[0].modified[0];
const filename = modified.split('/').pop();
const basename = filename.replace('_COMPLETE.txt', '').replace(/_/g, ' ');

// Map filename to product data
const productMap = {
  'AI BUSINESS PROMPT PACK': {
    name: 'AI Business Prompt Pack',
    url_name: 'ai-business-prompt-pack',
    price: 2700,
    description: '50 complete AI prompts covering copywriting, sales emails, social media, product descriptions, and cold outreach. Ready to use immediately. 768 lines of pure value.'
  },
  'REAL ESTATE': {
    name: 'Real Estate Copywriting Kit',
    url_name: 'real-estate-copywriting-kit',
    price: 1900,
    description: '5 complete email sequences, 3 listing templates, 30 social posts. Use immediately - all templates ready. 454 lines.'
  },
  'POD': {
    name: 'POD Design Prompt Bundle',
    url_name: 'pod-design-prompt-bundle',
    price: 2200,
    description: '100+ AI design prompts organized by niche. Ready for Midjourney/DALL-E. Includes niche analysis and Etsy optimization. 419 lines.'
  },
  'SEO': {
    name: 'Programmatic SEO Starter Kit',
    url_name: 'programmatic-seo-starter-kit',
    price: 2900,
    description: '100+ keywords with search volume + 25 content outlines + 20-point checklist + schema markup + 90-day plan. 389 lines.'
  },
  'SOCIAL MEDIA': {
    name: 'Social Media Content Engine',
    url_name: 'social-media-content-engine',
    price: 1700,
    description: '90-day complete content calendar with 5 platform formulas, 15 caption templates, 3 video scripts. Batch creation guide. 327 lines.'
  }
};

const product = productMap[basename.toUpperCase()];

if (!product) {
  throw new Error(`Product not found for file: ${filename}`);
}

return {
  filename,
  ...product,
  tags: 'ai,prompts,business,automation',
  currency: 'usd',
  license: 'PLv1'
};

const response = $input.first().json;
if (response.product) {
  return {
    status: 'SUCCESS',
    product_name: response.product.name,
    product_id: response.product.id,
    url: response.product.short_url,
    timestamp: new Date().toISOString()
  };
} else {
  throw new Error('Product creation failed: ' + JSON.stringify(response));
}
